import { describe, expect, it } from 'vitest'
import type { RawAppointment } from '@/types'
import {
  formatDate,
  formatCurrency,
  formatDateCompact,
  formatDatespan,
  formatDatetime,
  formatDuration,
  formatTimespan,
} from '@/utils'

const toUtcIso = (year: number, month: number, day: number, hours = 0, minutes = 0) =>
  new Date(Date.UTC(year, month - 1, day, hours, minutes)).toISOString()

const toNaiveIso = (year: number, month: number, day: number, hours = 0, minutes = 0) => {
  const pad = (n: number) => String(n).padStart(2, '0')
  const date = `${year}-${pad(month)}-${pad(day)}`
  return hours === 0 && minutes === 0 ? date : `${date}T${pad(hours)}:${pad(minutes)}:00`
}

const appointment = (fields: Partial<RawAppointment>): RawAppointment => ({
  sort_index: 0,
  ...fields,
})

const NBSP = '\u00A0'

describe('formatDate', () => {
  const cases: Array<[Date, string]> = [
    [new Date(Date.UTC(2024, 0, 15)), '15. Januar 2024'],
    [new Date(Date.UTC(2024, 2, 9)), '9. März 2024'],
    [new Date(Date.UTC(2024, 11, 1)), '1. Dezember 2024'],
  ]
  for (const [input, expected] of cases) {
    it(`formats ${input.toISOString()} as ${expected}`, () => {
      expect(formatDate(input)).toBe(expected)
    })
  }
})

describe('formatDatetime', () => {
  const cases: Array<[string, string]> = [
    [toUtcIso(2024, 1, 15, 14, 30), 'Mo., 15. Jan. 2024, 14:30 Uhr'],
    [toUtcIso(2024, 3, 9, 9, 5), 'Sa., 9. März 2024, 9:05 Uhr'],
    [toUtcIso(2024, 12, 31, 23, 59), 'Di., 31. Dez. 2024, 23:59 Uhr'],
  ]
  for (const [input, expected] of cases) {
    it(`formats ${input} as ${expected}`, () => {
      expect(formatDatetime(input)).toBe(expected)
    })
  }
})

describe('formatDateCompact', () => {
  const cases: Array<[string, string]> = [
    [toUtcIso(2024, 1, 15, 14, 30), 'Mo., 15. Jan., 14:30 Uhr'],
    [toUtcIso(2024, 3, 9, 9, 5), 'Sa., 9. März, 9:05 Uhr'],
    [toUtcIso(2024, 12, 31, 23, 59), 'Di., 31. Dez., 23:59 Uhr'],
  ]
  for (const [input, expected] of cases) {
    it(`formats ${input} as ${expected}`, () => {
      expect(formatDateCompact(input)).toBe(expected)
    })
  }
})

describe('formatDatespan', () => {
  describe('date-only (start_date / end_date)', () => {
    it('single day renders just the start in long form (German locale)', () => {
      expect(
        formatDatespan(appointment({ start_date: '2024-01-15', end_date: '2024-01-15' })),
      ).toBe('Mo., 15. Jan. 2024')
    })

    it('multi-day span renders both days joined with a dash (German locale)', () => {
      expect(
        formatDatespan(appointment({ start_date: '2024-01-15', end_date: '2024-01-18' })),
      ).toBe('Mo., 15. Jan. 2024 - Do., 18. Jan. 2024')
    })

    it('span across months and years (German locale)', () => {
      expect(
        formatDatespan(appointment({ start_date: '2024-12-30', end_date: '2025-01-02' })),
      ).toBe('Mo., 30. Dez. 2024 - Do., 2. Jan. 2025')
    })
  })

  describe('datetime-only (start_date_time / end_date_time)', () => {
    it('same-calendar-day collapse renders only the start (default locale, no de)', () => {
      expect(
        formatDatespan(
          appointment({
            start_date_time: toNaiveIso(2024, 1, 15, 14, 30),
            end_date_time: toNaiveIso(2024, 1, 15, 16, 30),
          }),
        ),
      ).toBe('Mon, 15. Jan 2024')
    })

    it('1-minute difference collapse renders only the start (tracer branch)', () => {
      expect(
        formatDatespan(
          appointment({
            start_date_time: toNaiveIso(2024, 1, 15, 14, 30),
            end_date_time: toNaiveIso(2024, 1, 15, 14, 31),
          }),
        ),
      ).toBe('Mon, 15. Jan 2024')
    })

    it('cross-midnight span (different calendar days) renders both endpoints (default locale)', () => {
      expect(
        formatDatespan(
          appointment({
            start_date_time: toNaiveIso(2024, 1, 15, 23, 30),
            end_date_time: toNaiveIso(2024, 1, 16, 0, 30),
          }),
        ),
      ).toBe('Mon, 15. Jan 2024 - Tue, 16. Jan 2024')
    })

    it('multi-day datetime span renders both endpoints (default locale)', () => {
      expect(
        formatDatespan(
          appointment({
            start_date_time: toNaiveIso(2024, 1, 15, 14, 30),
            end_date_time: toNaiveIso(2024, 1, 18, 10, 0),
          }),
        ),
      ).toBe('Mon, 15. Jan 2024 - Thu, 18. Jan 2024')
    })
  })

  describe('no dates', () => {
    it('throws when neither date nor datetime range is present', () => {
      expect(() => formatDatespan(appointment({}))).toThrow('Appointment has no start or end date')
    })

    it('throws with only a start_date', () => {
      expect(() => formatDatespan(appointment({ start_date: '2024-01-15' }))).toThrow(
        'Appointment has no start or end date',
      )
    })

    it('throws with only a start_date_time', () => {
      expect(() =>
        formatDatespan(appointment({ start_date_time: toNaiveIso(2024, 1, 15, 14, 30) })),
      ).toThrow('Appointment has no start or end date')
    })
  })
})

describe('formatTimespan', () => {
  it('returns ganztägig for all-day date range', () => {
    expect(formatTimespan(appointment({ start_date: '2024-01-15', end_date: '2024-01-15' }))).toBe(
      'ganztägig',
    )
  })

  it('formats datetime range as start - end Uhr', () => {
    expect(
      formatTimespan(
        appointment({
          start_date_time: toNaiveIso(2024, 1, 15, 14, 30),
          end_date_time: toNaiveIso(2024, 1, 15, 16, 45),
        }),
      ),
    ).toBe('14:30 - 16:45 Uhr')
  })

  it('1-minute difference still formats as a normal time range (no same-day collapse branch here)', () => {
    expect(
      formatTimespan(
        appointment({
          start_date_time: toNaiveIso(2024, 1, 15, 14, 30),
          end_date_time: toNaiveIso(2024, 1, 15, 14, 31),
        }),
      ),
    ).toBe('14:30 - 14:31 Uhr')
  })

  it('throws on empty appointment', () => {
    expect(() => formatTimespan(appointment({}))).toThrow(
      'Appointment has no start or end date time',
    )
  })

  it('throws with only a start_date set', () => {
    expect(() => formatTimespan(appointment({ start_date: '2024-01-15' }))).toThrow(
      'Appointment has no start or end date time',
    )
  })
})

describe('formatDuration', () => {
  const cases: Array<[number, string]> = [
    [0, ''],
    [30, '30 Minuten'],
    [60, '1 Stunde'],
    [90, '1 Stunde und 30 Minuten'],
    [120, '2 Stunden'],
    [150, '2 Stunden und 30 Minuten'],
    [180, '3 Stunden'],
  ]
  for (const [input, expected] of cases) {
    it(`formats ${input} minutes as "${expected}"`, () => {
      expect(formatDuration(input)).toBe(expected)
    })
  }
})

describe('formatCurrency', () => {
  const cases: Array<[number, string]> = [
    [0, `0,00${NBSP}€`],
    [9.99, `9,99${NBSP}€`],
    [1000, `1.000,00${NBSP}€`],
    [1234.5, `1.234,50${NBSP}€`],
    [-5, `-5,00${NBSP}€`],
  ]
  for (const [input, expected] of cases) {
    it(`formats ${input} as ${expected}`, () => {
      expect(formatCurrency(input)).toBe(expected)
    })
  }

  it('returns the original value when not coercible to a number', () => {
    expect(formatCurrency('not-a-number' as unknown as number)).toBe('not-a-number')
  })
})

import { describe, expect, it } from 'vitest'
import { http, HttpResponse } from 'msw'
import { manageSubscription, sendContactMessage } from '@/api/forms'
import { server } from '../mocks/server'
import {
  CONTACT_MESSAGE_URL,
  NEWS_SUBSCRIBE_URL,
  NEWS_UNSUBSCRIBE_URL,
} from '../mocks/handlers/forms'

describe('sendContactMessage — mutating POST contact route', () => {
  it('asserts request shape: URL, POST, Content-Type application/json, body shape {type, to, name, email, phone, message, token}', async () => {
    let capturedMethod: string | undefined = undefined
    let capturedContentType: string | null = null
    let capturedUrl: string | undefined = undefined
    let capturedBody: any = undefined
    server.use(
      http.post(CONTACT_MESSAGE_URL, async ({ request }) => {
        capturedMethod = request.method
        capturedContentType = request.headers.get('Content-Type')
        capturedUrl = request.url
        capturedBody = await request.json()
        return HttpResponse.json({ success: true, message: 'sent' })
      }),
    )

    const response = await sendContactMessage(
      'vorstand@sv-eutingen.de',
      '  Max Mustermann  ',
      '  max@example.org  ',
      ' 0176 1234567 ',
      '  Hallo Welt  ',
      'captcha-token',
    )

    expect(response.ok).toBe(true)
    expect(capturedMethod).toBe('POST')
    expect(new URL(capturedUrl!).pathname).toBe('/api/contact/message')
    expect(capturedContentType).toBe('application/json')
    expect(capturedBody).toEqual({
      type: 'General',
      to: 'vorstand@sv-eutingen.de',
      name: 'Max Mustermann',
      email: 'max@example.org',
      phone: '0176 1234567',
      message: 'Hallo Welt',
      token: 'captcha-token',
    })
  })

  it('omits phone (sets it undefined) when the caller passes `undefined`', async () => {
    let capturedBody: any
    server.use(
      http.post(CONTACT_MESSAGE_URL, async ({ request }) => {
        capturedBody = await request.json()
        return HttpResponse.json({ success: true })
      }),
    )

    await sendContactMessage('recip', 'Max', 'max@example.org', undefined, 'msg', 'tok')

    expect(capturedBody).toEqual({
      type: 'General',
      to: 'recip',
      name: 'Max',
      email: 'max@example.org',
      phone: undefined,
      message: 'msg',
      token: 'tok',
    })
  })

  it('returns the raw 2xx Response (caller proceeds with response.ok)', async () => {
    server.use(http.post(CONTACT_MESSAGE_URL, () => HttpResponse.json({ success: true })))

    const response = await sendContactMessage('to', 'n', 'e', undefined, 'm', 't')
    expect(response.ok).toBe(true)
    expect(response.status).toBe(200)
  })

  it('failure path: returns the raw non-2xx Response without throwing', async () => {
    server.use(
      http.post(CONTACT_MESSAGE_URL, () =>
        HttpResponse.json({ message: 'invalid' }, { status: 422 }),
      ),
    )

    const response = await sendContactMessage('to', 'n', 'e', undefined, 'm', 't')
    expect(response.ok).toBe(false)
    expect(response.status).toBe(422)
  })

  it('failure path: 500 also surfaces as raw Response', async () => {
    server.use(http.post(CONTACT_MESSAGE_URL, () => HttpResponse.json({}, { status: 500 })))
    const response = await sendContactMessage('to', 'n', 'e', undefined, 'm', 't')
    expect(response.ok).toBe(false)
    expect(response.status).toBe(500)
  })
})

describe('manageSubscription — mutating POST news route', () => {
  it('asserts request shape for subscribe=true: URL, POST, Content-Type, body {email, types, token}', async () => {
    let capturedMethod: string | undefined = undefined
    let capturedContentType: string | null = null
    let capturedUrl: string | undefined = undefined
    let capturedBody: any = undefined
    server.use(
      http.post(NEWS_SUBSCRIBE_URL, async ({ request }) => {
        capturedMethod = request.method
        capturedContentType = request.headers.get('Content-Type')
        capturedUrl = request.url
        capturedBody = await request.json()
        return HttpResponse.json({ success: true })
      }),
    )

    const response = await manageSubscription(
      true,
      'subscriber@example.org',
      true,
      false,
      true,
      'token-7',
    )

    expect(response.ok).toBe(true)
    expect(capturedMethod).toBe('POST')
    expect(capturedContentType).toBe('application/json')
    expect(new URL(capturedUrl!).pathname).toBe('/api/news/subscribe')
    expect(capturedBody).toEqual({
      email: 'subscriber@example.org',
      types: ['General', 'Events'],
      token: 'token-7',
    })
  })

  it('asserts request shape for subscribe=false: POST /news/unsubscribe', async () => {
    let capturedUrl: string | undefined = undefined
    let capturedBody: any
    server.use(
      http.post(NEWS_UNSUBSCRIBE_URL, async ({ request }) => {
        capturedUrl = request.url
        capturedBody = await request.json()
        return HttpResponse.json({ success: true })
      }),
    )

    const response = await manageSubscription(
      false,
      'unsub@example.org',
      true,
      true,
      true,
      'token-9',
    )

    expect(response.ok).toBe(true)
    expect(new URL(capturedUrl!).pathname).toBe('/api/news/unsubscribe')
    expect(capturedBody).toEqual({
      email: 'unsub@example.org',
      types: ['General', 'Fitness', 'Events'],
      token: 'token-9',
    })
  })

  it('emits an empty `types` array when no category is selected', async () => {
    let capturedBody: any
    server.use(
      http.post(NEWS_SUBSCRIBE_URL, async ({ request }) => {
        capturedBody = await request.json()
        return HttpResponse.json({ success: true })
      }),
    )

    await manageSubscription(true, 'e@example.org', false, false, false, 'tok')
    expect(capturedBody).toEqual({ email: 'e@example.org', types: [], token: 'tok' })
  })

  it('returns the raw 2xx Response', async () => {
    server.use(http.post(NEWS_SUBSCRIBE_URL, () => HttpResponse.json({ success: true })))
    const response = await manageSubscription(true, 'e', true, false, false, 'tok')
    expect(response.ok).toBe(true)
    expect(response.status).toBe(200)
  })

  it('failure path: returns the raw 4xx Response without throwing (subscribe path)', async () => {
    server.use(
      http.post(NEWS_SUBSCRIBE_URL, () => HttpResponse.json({ message: 'bad' }, { status: 400 })),
    )
    const response = await manageSubscription(true, 'e', true, false, false, 'tok')
    expect(response.ok).toBe(false)
    expect(response.status).toBe(400)
  })

  it('failure path: returns the raw 5xx Response without throwing (unsubscribe path)', async () => {
    server.use(http.post(NEWS_UNSUBSCRIBE_URL, () => HttpResponse.json({}, { status: 503 })))
    const response = await manageSubscription(false, 'e', true, false, false, 'tok')
    expect(response.ok).toBe(false)
    expect(response.status).toBe(503)
  })
})

