import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import {
  checkRequiredInput,
  checkRequiredSelect,
  clearCustomValidityOnInput,
  clearCustomValidityOnSelect,
  validateIbanInput,
} from '@/client/forms'

const VALID_IBAN = 'DE89 3704 0044 0532 0130 00'
const MALFORMED_IBAN = 'DE00 0000 0000 0000 0000 00'

const validitySpies = () => {
  const setInput = vi.fn()
  const reportInput = vi.fn(() => false)
  const setSelect = vi.fn()
  const reportSelect = vi.fn(() => false)
  const setTextarea = vi.fn()
  const reportTextarea = vi.fn(() => false)
  Object.defineProperty(HTMLInputElement.prototype, 'setCustomValidity', {
    configurable: true,
    value: setInput,
  })
  Object.defineProperty(HTMLInputElement.prototype, 'reportValidity', {
    configurable: true,
    value: reportInput,
  })
  Object.defineProperty(HTMLSelectElement.prototype, 'setCustomValidity', {
    configurable: true,
    value: setSelect,
  })
  Object.defineProperty(HTMLSelectElement.prototype, 'reportValidity', {
    configurable: true,
    value: reportSelect,
  })
  Object.defineProperty(HTMLTextAreaElement.prototype, 'setCustomValidity', {
    configurable: true,
    value: setTextarea,
  })
  Object.defineProperty(HTMLTextAreaElement.prototype, 'reportValidity', {
    configurable: true,
    value: reportTextarea,
  })
  return { setInput, reportInput, setSelect, reportSelect, setTextarea, reportTextarea }
}

describe('checkRequiredInput', () => {
  let spies: ReturnType<typeof validitySpies>

  beforeEach(() => {
    spies = validitySpies()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('returns true and does not touch validity when the input has a non-empty value', () => {
    const input = document.createElement('input')
    input.value = 'Max Mustermann'

    expect(checkRequiredInput(input, 'Pflichtfeld')).toBe(true)
    expect(spies.setInput).not.toHaveBeenCalled()
    expect(spies.reportInput).not.toHaveBeenCalled()
  })

  it('treats whitespace-only values as empty: sets the message, reports validity, returns false', () => {
    const input = document.createElement('input')
    input.value = '   '

    expect(checkRequiredInput(input, 'Pflichtfeld')).toBe(false)
    expect(spies.setInput).toHaveBeenCalledWith('Pflichtfeld')
    expect(spies.reportInput).toHaveBeenCalledTimes(1)
  })

  it('sets the custom validity message and calls reportValidity when the input is empty', () => {
    const input = document.createElement('input')

    expect(checkRequiredInput(input, 'Bitte Namen angeben')).toBe(false)
    expect(spies.setInput).toHaveBeenCalledWith('Bitte Namen angeben')
    expect(spies.reportInput).toHaveBeenCalledTimes(1)
  })

  it('works for HTMLTextAreaElement and propagates the error message', () => {
    const textarea = document.createElement('textarea')

    expect(checkRequiredInput(textarea, 'Bitte Nachricht angeben')).toBe(false)
    expect(spies.setTextarea).toHaveBeenCalledWith('Bitte Nachricht angeben')
    expect(spies.reportTextarea).toHaveBeenCalledTimes(1)
  })

  it('returns true for null input without touching the prototype', () => {
    expect(checkRequiredInput(null, 'Pflichtfeld')).toBe(true)
    expect(spies.setInput).not.toHaveBeenCalled()
    expect(spies.reportInput).not.toHaveBeenCalled()
  })

  it('returns true for undefined input without touching the prototype', () => {
    expect(checkRequiredInput(undefined, 'Pflichtfeld')).toBe(true)
    expect(spies.setInput).not.toHaveBeenCalled()
    expect(spies.reportInput).not.toHaveBeenCalled()
  })
})

describe('checkRequiredSelect', () => {
  let spies: ReturnType<typeof validitySpies>

  beforeEach(() => {
    spies = validitySpies()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('returns true and does not touch validity when a value is selected', () => {
    const select = document.createElement('select')
    const option = document.createElement('option')
    option.value = 'general'
    select.append(option)
    select.value = 'general'

    expect(checkRequiredSelect(select, 'Bitte auswählen')).toBe(true)
    expect(spies.setSelect).not.toHaveBeenCalled()
    expect(spies.reportSelect).not.toHaveBeenCalled()
  })

  it('sets the custom validity message and reports validity for an empty value', () => {
    const select = document.createElement('select')

    expect(checkRequiredSelect(select, 'Bitte Auswahl treffen')).toBe(false)
    expect(spies.setSelect).toHaveBeenCalledWith('Bitte Auswahl treffen')
    expect(spies.reportSelect).toHaveBeenCalledTimes(1)
  })

